package cm.capstone.donsang.service;
import cm.capstone.donsang.model.*; import cm.capstone.donsang.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.oauth2.client.authentication.OAuth2AuthenticationToken; import org.springframework.security.web.authentication.AuthenticationSuccessHandler; import org.springframework.stereotype.Service; import jakarta.servlet.http.*; import java.io.IOException; import java.time.LocalDateTime; import static cm.capstone.donsang.model.Enums.*;
@Service @RequiredArgsConstructor public class OAuth2Service implements AuthenticationSuccessHandler {
 private final UtilisateurRepository users; private final ProfilDonneurRepository donneurs; private final PasswordEncoder encoder;
 @Override public void onAuthenticationSuccess(HttpServletRequest req,HttpServletResponse res,Authentication auth)throws IOException{var token=(OAuth2AuthenticationToken)auth;var attrs=token.getPrincipal().getAttributes();String email=(String)attrs.get("email");String name=(String)attrs.getOrDefault("name","Donneur Google");var u=users.findByEmail(email).orElseGet(()->users.save(Utilisateur.builder().email(email).nom(name).motDePasse(encoder.encode("GOOGLE_ONLY")).methodeConnexion(MethodeConnexion.GOOGLE).role(Role.DONNEUR).compteActif(true).dateCreation(LocalDateTime.now()).build()));if(u.getRole()!=Role.DONNEUR){res.sendRedirect("/login?error=google-role");return;}if(donneurs.findByUtilisateurId(u.getId()).isEmpty())donneurs.save(ProfilDonneur.builder().utilisateur(u).groupeSanguin("O+").build());u.setDerniereConnexion(LocalDateTime.now());users.save(u);res.sendRedirect("/dashboard");}
}
